tool.command:
export NUMBA_CACHE_DIR="\${TMPDIR:-/tmp}/numba" && mkdir -p output_dir && link_laz_input() { link_src="\$1"; link_dir="\$2"; link_name="\$3"; case "\$link_name" in *.laz|*.las|*.LAZ|*.LAS) link_out="\$link_name" ;; *) link_out="\$link_name.laz" ;; esac; ln -s "\$link_src" "\$link_dir/\$link_out"; } && link_copc_input() { link_src="\$1"; link_dir="\$2"; link_name="\$3"; case "\$link_name" in *.copc.laz|*.COPC.LAZ) link_out="\$link_name" ;; *.laz|*.las|*.LAZ|*.LAS) link_out="\${link_name%.*}.copc.laz" ;; *) link_out="\$link_name.copc.laz" ;; esac; ln -s "\$link_src" "\$link_dir/\$link_out"; } &&
#if $operation.task == 'tile': mkdir -p input_dir && #for $f in $operation.input_files: link_laz_input '$f' input_dir '${f.element_identifier}' && #end for python -u /src/run.py --task tile --input-dir input_dir --output-dir output_dir --tile-length '$operation.tile_length' --tile-buffer '$operation.tile_buffer' #if $operation.tiling_threshold: --tiling-threshold '$operation.tiling_threshold' #end if --resolution-1 '$operation.resolution_1' --resolution-2 '$operation.resolution_2' --subsampling-method '$operation.subsampling_method' $operation.output_copc_res1 $operation.output_copc_res2 --chunk-size '$operation.chunk_size' #if $operation.num_spatial_chunks: --num-spatial-chunks '$operation.num_spatial_chunks' #else --num-spatial-chunks \${GALAXY_SLOTS:-4} #end if --workers \${GALAXY_SLOTS:-4} --threads \${GALAXY_SLOTS:-4}
