ization_json' #end if --threedtrees-dims '$operation.threedtrees_dims' --threedtrees-suffix '$operation.threedtrees_suffix' --chunk-size '$operation.chunk_size' #if $operation.num_spatial_chunks: --num-spatial-chunks '$operation.num_spatial_chunks' #else --num-spatial-chunks \${GALAXY_SLOTS:-4} #end if --workers \${GALAXY_SLOTS:-4}
#elif $operation.task == 'create_merged_file': mkdir -p original_with_predictions && #for $f in $operation.original_with_predictions: link_laz_input '$f' original_with_predictions '${f.element_identifier}' && #end for #if $operation.staged_copc_files: mkdir -p staged_copc && #for $f in $operation.staged_copc_files: link_copc_input '$f' staged_copc '${f.element_identifier}' && #end for #end if python -u /src/run.py --task create_merged_file --original-with-predictions-dir original_with_predictions --output-dir output_dir #if $operation.staged_copc_files: --staged-copc-dir staged_copc #end if #if $operation.standardization_json: --standardization-json '$operation.standardization_json' #end if --resolution-1 '$operation.resolution_1' --resolution-2 '$operation.resolution_2' --merged-resolutions '$operation.merged_resolutions' --merged-output-formats '$operation.merged_output_formats' #if $operation.num_spatial_chunks: --num-spatial-chunks '$operation.num_spatial_chunks' #else --num-spatial-chunks \${GALAXY_SLOTS:-4} #end if --workers \${GALAXY_SLOTS:-4} #end if
